		/** 
		 * Tests creating a new Underwriter.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Underwriter");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Underwriter" );

			try {            
				Underwriter entity = UnderwriterService.getUnderwriterInstance().createUnderwriter( generateNewEntity() );
				thePrimaryKey = entity.getUnderwriterId();
				LOGGER.info( "-- Successfully created a Underwriter with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Underwriter. 
		 */
		public Underwriter testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Underwriter" );

			Underwriter entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Underwriter with primary key" );
			msg.append( thePrimaryKey );
			
			UnderwriterFetchOneSummary fetchOneSummary = new UnderwriterFetchOneSummary( thePrimaryKey );

			try {
				entity = UnderwriterService.getUnderwriterInstance().getUnderwriter( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Underwriter " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Underwriter.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Underwriter." );

			StringBuilder msg = new StringBuilder( "Failed to update a Underwriter : " );        
			Underwriter entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Underwriter." );

				// for use later on...
				thePrimaryKey = entity.getUnderwriterId();

				UnderwriterService proxy = UnderwriterService.getUnderwriterInstance();            
				proxy.updateUnderwriter( entity );   

				LOGGER.info( "-- Successfully saved Underwriter - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Underwriter.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Underwriter." );

			try{
			    Underwriter entity = testRead(); 
				UnderwriterService.getUnderwriterInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Underwriter with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Underwriter with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Underwriters.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Underwriters:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Underwriter : " );        
			List<Underwriter> collection  = null;

			try {
				// call the static get method on the UnderwriterService
				collection = UnderwriterService.getUnderwriterInstance().getAllUnderwriter();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Underwriter entity = null;            
					Iterator<Underwriter> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getUnderwriterId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

